function sound(name='Impact',gain=1){if(prefs.sfx===0)return;const context=dock.context,buffer=audio.buffers.get(name);if(context&&buffer){const source=context.createBufferSource(),volume=context.createGain();source.buffer=buffer;volume.gain.value=Math.min(1,prefs.sfx*.22*gain);source.connect(volume).connect(context.destination);audio.sources.push(source);if(audio.sources.length>14){try{audio.sources.shift().stop();}catch{}}source.onended=()=>{source.disconnect();volume.disconnect();const i=audio.sources.indexOf(source);if(i>=0)audio.sources.splice(i,1);};source.start();return;}if(context&&!audio.loading.has(name)){audio.loading.add(name);fetch('assets/audio/'+name+'.mp3').then(r=>r.arrayBuffer()).then(b=>context.decodeAudioData(b)).then(b=>audio.buffers.set(name,b)).catch(()=>audio.loading.delete(name));}const a=audio.voices[audio.cursor++%audio.voices.length];a.pause();a.src='assets/audio/'+name+'.mp3';a.volume=Math.min(1,prefs.sfx*.22*gain);a.play().catch(()=>{});}

function music(mode){dock.mode(mode);}
