function modal(title,body,actions){const tip=$('card-tooltip');if(tip)tip.hidden=true;$('modal').replaceChildren();const h=document.createElement('h2');h.id='modal-title';h.textContent=title;$('modal').append(h,body);const row=document.createElement('div');row.className='modal-actions';for(const [label,fn,primary=false]of actions){const b=document.createElement('button');b.textContent=label;b.className=primary?'primary':'';b.onclick=fn;row.append(b);}$('modal').append(row);$('overlay').hidden=false;requestAnimationFrame(()=>$('modal').querySelector('button,input')?.focus());}
function closeModal(){const saved=game.screenStack?.pop();if(saved){game.state=saved.state;game.previous=saved.previous;$('modal').replaceChildren(...saved.nodes);$('overlay').hidden=saved.hidden;saved.focus?.focus();}else{$('overlay').hidden=true;game.state=game.previous;}keys.clear();}
function openScreen(state,title,content,actions=null){game.screenStack??=[];game.screenStack.push({state:game.state,previous:game.previous,nodes:[...$('modal').childNodes],hidden:$('overlay').hidden,focus:document.activeElement});game.previous=game.state;game.state=state;keys.clear();modal(title,content,actions??[['RETURN',closeModal,true]]);}

function paragraph(text,className=''){const p=document.createElement('p');p.textContent=text;p.className=className;return p;}
function setPlayState(){game.state=game.practice?'testing':'playing';$('menu').hidden=true;$('hud').hidden=false;$('overlay').hidden=true;document.body.classList.add('playing');music('game');}
function goMenu(){city.setRangeMode(false);if(suspendedRun){discardSuspended();}game.screenStack=[];game.hand=null;game.pendingDraft=0;fx.clear();game.state='menu';$('menu').hidden=false;$('hud').hidden=true;$('overlay').hidden=true;document.body.classList.remove('playing');$('health-edge').classList.remove('active');audio.alarm.pause();clearTimeout(alarmTimer);clearInterval(alarmFade);music('menu');keys.clear();for(const e of game.enemies){e.alive=false;e.mesh.visible=false;}for(const s of game.shots){s.active=false;s.mesh.visible=false;}for(const g of game.gems)g.active=false;game.hazards.length=0;for(const s of game.stations){s.mesh.visible=true;s.used=false;}game.challenge=null;for(const o of systems.objectives){o.mesh.visible=false;o.label.hidden=true;}for(const a of systems.spirits)if(a)a.mesh.visible=false;renderLibrary();}

function renderLibrary(){workbench.render();}
function settings(){if(game.state==='settings')return;const content=document.createElement('div');content.append(paragraph('Preferences save in this browser. Gameplay music continues through menus and drafts.','muted'));
for(const [key,label,min,max,step]of[['music','MUSIC',0,1,.01],['sfx','SOUND EFFECTS',0,1,.01],['intensity','IMPACT PARTICLES',0,1.5,.01],['zoom','CAMERA DISTANCE',22,58,.5],['bloom','BLOOM',0,1,.01],['flash','IMPACT LIGHTING',0,1,.01],['shake','CAMERA SHAKE',0,1,.01]]){const row=document.createElement('label');row.className='setting';const caption=paragraph(label),input=document.createElement('input'),value=document.createElement('output');input.type='range';Object.assign(input,{min,max,step,value:prefs[key]});input.setAttribute('aria-label',label);const update=()=>value.textContent=key==='zoom'?Number(input.value).toFixed(1):Math.round(input.value*100)+'%';input.oninput=()=>{prefs[key]=+input.value;fx.intensity=prefs.intensity;audio.alarm.volume=prefs.sfx*.45;fx.userFlash=prefs.reducedFlashes?Math.min(.2,prefs.flash):prefs.flash;dock.volume();if(composer)composer.passes[1].strength=prefs.bloom*.65;update();save();};update();row.append(caption,input,value);content.append(row);}
for(const [key,label]of[['adaptive','ADAPTIVE RESOLUTION'],['reducedFlashes','REDUCED FLASHES'],['damageNumbers','DAMAGE NUMBERS']]){const row=document.createElement('label');row.className='performance-toggle';const input=document.createElement('input');input.type='checkbox';input.checked=prefs[key];input.onchange=()=>{prefs[key]=input.checked;applyQuality();save();};row.append(input,document.createTextNode(' '+label));content.append(row);}
const quality=document.createElement('button');quality.textContent='QUALITY / '+prefs.quality.toUpperCase();quality.onclick=()=>{prefs.quality=prefs.quality==='low'?'high':'low';quality.textContent='QUALITY / '+prefs.quality.toUpperCase();applyQuality();save();};content.append(quality);
const display=document.createElement('select');display.setAttribute('aria-label','Display mode');for(const [id,name]of[['window','BROWSER WINDOW'],['fullscreen','FULLSCREEN']]){const o=document.createElement('option');o.value=id;o.textContent=name;display.append(o);}display.value=document.fullscreenElement?'fullscreen':'window';const applyDisplay=document.createElement('button');applyDisplay.textContent='APPLY DISPLAY MODE';applyDisplay.onclick=async()=>{try{if(display.value==='window'){if(document.fullscreenElement)await document.exitFullscreen();}else await document.documentElement.requestFullscreen();resize();}catch{toast('This browser did not allow the fullscreen change.');}display.value=document.fullscreenElement?'fullscreen':'window';};content.append(paragraph('DISPLAY — browsers support windowed and fullscreen. OS borderless/exclusive modes belong to the Windows edition. Choose a mode, then apply.','muted'),display,applyDisplay);
const targeting=document.createElement('select');targeting.setAttribute('aria-label','Target priority');['NEAREST','STRONGEST','MARKED'].forEach((name,i)=>{const o=document.createElement('option');o.value=i;o.textContent=name;targeting.append(o);});targeting.value=prefs.targetPriority;targeting.onchange=()=>{prefs.targetPriority=+targeting.value;save();};content.append(paragraph('AUTO-TARGET PRIORITY / Q TO CYCLE','muted'),targeting);
for(const [action,label]of[['boost','BOOST'],['interact','INTERACT'],['inspect','INSPECT / RESUME DRAFT'],['mark','MARK TARGET']]){const b=document.createElement('button');b.className='binding';b.textContent=label+' / '+prefs.bindings[action];b.onclick=()=>{b.textContent='PRESS A KEY (ESC TO CANCEL)';const capture=e=>{e.preventDefault();e.stopImmediatePropagation();if(e.code!=='Escape'){if(['KeyW','KeyA','KeyS','KeyD','KeyQ'].includes(e.code)||Object.entries(prefs.bindings).some(([k,v])=>k!==action&&v===e.code))toast('That key is already assigned.');else{prefs.bindings[action]=e.code;save();}}b.textContent=label+' / '+prefs.bindings[action];document.removeEventListener('keydown',capture,true);};document.addEventListener('keydown',capture,true);};content.append(b);}
const perf=paragraph(performanceText,'muted');perf.id='performance-settings';content.append(perf);const actions=[['SAVE & RETURN',closeModal,true],['TESTING RANGE',testingSetup]];if(game.practice){actions.unshift(['COMBAT REPORT',combatReport]);if(suspendedRun){actions.unshift(['RESUME SUSPENDED RUN',()=>restoreRun()]);actions.push(['END SUSPENDED RUN',()=>{restoreRun(true);endRun(false);}]);}else actions.push(['RETURN TO CODEX',goMenu]);}else if(game.state!=='menu')actions.unshift(['END RUN',()=>endRun(false)]);openScreen('settings','SETTINGS / SIGNAL CONFIGURATION',content,actions);}
