// Visible opt-in QA controls exercise the same game functions, without altering user saves.
if(new URLSearchParams(location.search).has('qa')){const bar=document.createElement('div');bar.style.cssText='position:fixed;bottom:0;left:0;z-index:20;display:flex;flex-wrap:wrap;max-width:100vw;gap:8px;background:#081823;padding:8px';for(const[label,fn]of[['QA END RUN',()=>endRun(false)],['QA + ESSENCE',()=>collect(xpCost(game.level,rules.progression))],['QA LOW HEALTH',()=>player.health=20],['QA RECOVER',()=>player.health=80],['QA CONTRACT',()=>{game.nearestSign=game.stations[0];offerChallenge();}],['QA UNLOCK ELITES',()=>game.time=200],['QA MUTATIONS',()=>{resetRun(true,rules.cards.map(c=>c.id));for(const w of game.weapons){w.rank=3;w.evolution=1;}for(let i=0;i<8;i++){const a=i/8*Math.PI*2;spawnEnemy(rules.enemies[9],player.position.clone().add(new T.Vector3(Math.cos(a)*2.7,0,Math.sin(a)*2.7)),true);}renderWeapons();}],['QA ALL SPELLS',()=>{resetRun(true,rules.cards.map(c=>c.id));for(let i=0;i<15;i++)spawnEnemy(rules.enemies[9],new T.Vector3((i%5-2)*2.5,0,-9-Math.floor(i/5)*2.5),true);spawnEnemy(rules.enemies[0],player.position.clone().add(new T.Vector3(1.7,0,0)),true);renderWeapons();}]]){const b=document.createElement('button');b.textContent=label;b.onclick=fn;bar.append(b);}document.body.append(bar);}

if(new URLSearchParams(location.search).has('qa')){const bar=document.createElement('div');bar.className='qa-navigation';bar.style.cssText='position:fixed;bottom:40px;left:8px;z-index:20;background:#061322;padding:6px;display:flex;gap:6px;font-size:10px';const roof=document.createElement('select');roof.setAttribute('aria-label','QA rooftop');for(const p of city.platforms){const option=document.createElement('option');option.value=city.platforms.indexOf(p);option.textContent='ROOF '+city.platforms.indexOf(p)+' / '+p.h+'m';roof.append(option);}const tier=document.createElement('select');tier.setAttribute('aria-label','QA enemy');for(const index of[0,6,9]){const option=document.createElement('option');option.value=index;option.textContent=rules.enemies[index].name;tier.append(option);}const b=document.createElement('button');b.textContent='QA ROOFTOP CHASE';b.onclick=()=>{const p=city.platforms[+roof.value];resetRun(true,['PulseDart']);game.weapons=[];player.position.set(p.x,p.h,p.z);player.art.mesh.position.copy(player.position);const enemy=spawnEnemy(rules.enemies[+tier.value],new T.Vector3(p.x,0,p.z),false,false,true);if(enemy){if(city.blocked(enemy.position.x,enemy.position.z,enemy.radius,enemy.position.y))enemy.position.set(0,0,-5);enemy.health=enemy.maxHealth=1e8;game.routeAudit={enemy,goal:player.position.clone(),started:game.time};city.updateFlow(player.position);}renderWeapons();};const report=document.createElement('output');report.id='qa-route-status';report.textContent='ROUTE TEST READY';bar.append(roof,tier,b,report);document.body.append(bar);}
